ssh openfang 'cat > /tmp/mcp_probe.py <<"PYEOF"
import urllib.request, json, re

URL = "http://127.0.0.1:7007/mcp/"
HDRS = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}

def post(body, sid=None, parse=True):
    h = dict(HDRS)
    if sid: h["mcp-session-id"] = sid
    req = urllib.request.Request(URL, method="POST", headers=h, data=json.dumps(body).encode())
    r = urllib.request.urlopen(req, timeout=15)
    new_sid = r.headers.get("mcp-session-id") or sid
    if not parse:
        return new_sid, None
    raw = r.read().decode()
    m = re.search(r"data: (.*)", raw)
    if not m and not raw.strip():
        return new_sid, None
    return new_sid, json.loads(m.group(1)) if m else json.loads(raw)

sid, _ = post({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"probe","version":"1"}}})
post({"jsonrpc":"2.0","method":"notifications/initialized"}, sid, parse=False)

sid, resp = post({
    "jsonrpc":"2.0","id":2,"method":"tools/call",
    "params":{"name":"actions_list","arguments":{"owner":"Liftitapp","repo":"services-domain","perPage":2,"page":1}}
}, sid)
content = resp.get("result",{}).get("content", [])
if resp.get("result",{}).get("isError"):
    print("ERROR:", json.dumps(resp, indent=2)[:600])
else:
    for c in content[:2]:
        text = c.get("text", "")
        print(text[:600])
        print("---")
PYEOF
sudo docker cp /tmp/mcp_probe.py openfang-mcp-github:/tmp/probe.py >/dev/null && sudo docker exec openfang-mcp-github python3 /tmp/probe.py' 2>&1 | grep -v "bind\|channel\|Could"

