def post(body, sid=None, parse=True):
    h = dict(HDRS)
    if sid: h["mcp-session-id"] = sid
    req = urllib.request.Request(URL, method="POST", headers=h, data=json.dumps(body).encode())
    r = urllib.request.urlopen(req, timeout=15)
    new_sid = r.headers.get("mcp-session-id") or sid
    if not parse: return new_sid, None
    raw = r.read().decode()
    m = re.search(r"data: (.*)", raw)
    if not m and not raw.strip(): return new_sid, None
    return new_sid, json.loads(m.group(1)) if m else json.loads(raw)

sid, _ = post({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"probe","version":"1"}}})
post({"jsonrpc":"2.0","method":"notifications/initialized"}, sid, parse=False)

sid, resp = post({
    "jsonrpc":"2.0","id":3,"method":"tools/call",
    "params":{"name":"actions_list","arguments":{
        "method":"list_workflow_runs","owner":"Liftitapp","repo":"services-domain","perPage":2,"page":1}}
}, sid)
content = resp.get("result",{}).get("content", [])
